<?php $page_title='Stock Transfers'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'transfers','can_view'); $msg='';
$prods=$pdo->query("SELECT * FROM products ORDER BY name")->fetchAll(); $whs=$pdo->query("SELECT * FROM warehouses ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $pid=(int)$_POST['product_id']; $from=(int)$_POST['from_warehouse_id']; $to=(int)$_POST['to_warehouse_id']; $qty=(int)$_POST['quantity']; $notes=clean($_POST['notes']??'');
 if($from===$to) $msg='Source and destination must differ.';
 else { try{ $pdo->beginTransaction(); $avail=$pdo->prepare("SELECT COALESCE(quantity,0) FROM stock WHERE product_id=? AND warehouse_id=?"); $avail->execute([$pid,$from]); if((int)$avail->fetchColumn() < $qty) throw new Exception('Insufficient stock in source warehouse.'); $no=gen_no('TRF'); $pdo->prepare("INSERT INTO transfers(transfer_no,product_id,from_warehouse_id,to_warehouse_id,quantity,notes,created_by) VALUES(?,?,?,?,?,?,?)")->execute([$no,$pid,$from,$to,$qty,$notes,$_SESSION['user_id']]); adjust_stock($pdo,$pid,$from,-$qty,'transfer_out',$no,$notes); adjust_stock($pdo,$pid,$to,$qty,'transfer_in',$no,$notes); $pdo->commit(); $msg='Transfer completed: '.$no; audit_log($pdo,'Transfer','transfers',"Transfer $no product $pid qty $qty"); }catch(Exception $e){ $pdo->rollBack(); $msg='Error: '.e($e->getMessage()); } }
}
$rows=$pdo->query("SELECT t.*, p.name as pname, w1.name as from_name, w2.name as to_name FROM transfers t JOIN products p ON p.id=t.product_id JOIN warehouses w1 ON w1.id=t.from_warehouse_id JOIN warehouses w2 ON w2.id=t.to_warehouse_id ORDER BY t.id DESC LIMIT 100")->fetchAll();
?>
<?php if($msg): ?><div class="alert alert-info"><?= e($msg) ?></div><?php endif; ?>
<div class="row"><div class="col-md-4"><div class="card p-3"><h5>New Transfer</h5><form method="post"><?= csrf_field() ?><label class="form-label">Product</label><select name="product_id" class="form-select mb-2" required><?php foreach($prods as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select><label class="form-label">From Warehouse</label><select name="from_warehouse_id" class="form-select mb-2" required><?php foreach($whs as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">To Warehouse</label><select name="to_warehouse_id" class="form-select mb-2" required><?php foreach($whs as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">Quantity</label><input type="number" min="1" name="quantity" class="form-control mb-2" required><label class="form-label">Notes</label><input name="notes" class="form-control mb-2"><button class="btn btn-primary">Transfer</button></form></div></div>
<div class="col-md-8"><div class="card p-3"><h5>Transfer History</h5><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Product</th><th>From</th><th>To</th><th>Qty</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['transfer_no']) ?></td><td><?= e($r['pname']) ?></td><td><?= e($r['from_name']) ?></td><td><?= e($r['to_name']) ?></td><td><?= (int)$r['quantity'] ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
